DAYS_MIN = inst['days']*1440.0

def des(mode, p):
    return {'mode':mode,'parameters':{k:float(v) for k,v in p.items()}}

def score(d):
    m = e.evaluate(d)
    return m['mean_tir'], m['max_trajectory_tbr70'], m['max_trajectory_tbr54'], m['minimum_glucose'], m['feasible']

print("=== CONSTANT: fine scan near sustainable region ===")
best=None
